# Validate saved 500-replay outputs without repeating any bootstrap draws.
# Arguments: workspace, output-directory, original-tables-directory, source-script.
args<-commandArgs(trailingOnly=TRUE)
ws<-normalizePath(if(length(args))args[1] else getwd(),winslash="/")
.libPaths(c(file.path(ws,"outputs/nhanes_nlr_depression_start_2026-10-20/runtime/library"),.libPaths()))
suppressPackageStartupMessages({library(survey);library(dplyr)})
replay_out<-if(length(args)>=2)args[2] else file.path(ws,"outputs/diabetes_manuscript_revision_20261104_v2/fext/denoise_500_replay")
ref<-if(length(args)>=3)args[3] else file.path(ws,"outputs/diabetes_manuscript_revision_20261104/supplement/tables")
source_file<-if(length(args)>=4)args[4] else file.path(ws,"outputs/diabetes_manuscript_revision_20261104/supplement/code/denoise_features_v5.R")
tables<-c("results_by_model","auc_by_model","coefficients_by_model","thresholds_by_model","family_curves","family_differences","family_differences_at_key_budgets")
checks<-lapply(tables,function(nm){
 a<-read.csv(file.path(replay_out,paste0(nm,".csv")),check.names=FALSE)
 b<-read.csv(file.path(ref,paste0("S12_information_",nm,".csv")),check.names=FALSE)
 stopifnot(identical(names(a),names(b)),nrow(a)==nrow(b))
 nums<-names(a)[vapply(a,is.numeric,logical(1))];nonnum<-setdiff(names(a),nums)
 stopifnot(all(vapply(nonnum,function(v)identical(as.character(a[[v]]),as.character(b[[v]])),logical(1))))
 do.call(rbind,lapply(nums,function(v){
  ok<-is.finite(a[[v]])&is.finite(b[[v]])
  data.frame(table=nm,field=v,n_rows=nrow(a),n_compared=sum(ok),NA_pattern_matches=identical(is.na(a[[v]]),is.na(b[[v]])),max_abs_difference=if(any(ok))max(abs(a[[v]][ok]-b[[v]][ok])) else NA_real_)
 }))
})
checks<-do.call(rbind,checks)
write.csv(checks,file.path(replay_out,"submitted_table_comparisons.csv"),row.names=FALSE)
x<-readRDS(file.path(replay_out,"replicate_curve_arrays.rds"))
mult<-read.csv(file.path(replay_out,"PSU_bootstrap_multipliers.csv"));status<-read.csv(file.path(replay_out,"replicate_status.csv"))
stopifnot(dim(x$CV$eval$boot)[3]==500,length(unique(mult$replicate))==500,length(unique(status$replicate))==500,all(checks$NA_pattern_matches),max(checks$max_abs_difference,na.rm=TRUE)<1e-10)
sm<-aggregate(cbind(finite_budget_points,undefined_budget_points)~curve,status,function(z)c(min=min(z),max=max(z)))
write.csv(sm,file.path(replay_out,"curve_definedness_summary.csv"),row.names=FALSE)
writeLines(c(paste("finalized",Sys.time()),"replicates 500","seed 20261103","The original computation completed and all bootstrap arrays/multipliers/metrics were saved. A live path-argument edit caused a trailing parser error in the checker. This separate finalizer validates the saved results without resampling; the replay source now parses successfully.","Source computation and seed retained; only paths adapted, graphics omitted, and bootstrap returns observed for multiplier export.","Uncertainty is conditional on submitted fixed equations, selected features, and thresholds; no bootstrap refitting or feature reselection.","Undefined curve regions below the family's minimum feasible referral share remain NA. Original >5% undefined-iteration reporting rule retained.",paste("source_md5",unname(tools::md5sum(source_file))),capture.output(sessionInfo())),file.path(replay_out,"execution_receipt.txt"))
print(checks);print(sm);cat("SAVED_DENOISE_500_REPLAY_VALIDATED\n")
